impl PrefixTree {
    pub fn new() -> Self {
        PrefixTree {
            root: PrefixTreeNode::new(),
        }
    }

    pub fn insert(&mut self, word: String) {
        let mut curr = &mut self.root;
        for c in word.chars() {
            let idx = (c as u8 - b'a') as usize;
            if curr.children[idx].is_none() {
                curr.children[idx] = Some(Box::new(PrefixTreeNode::new()));
            }
            curr = curr.children[idx].as_mut().unwrap();
        }
        curr.is_word = true;
    }

    pub fn search(&self, word: String) -> bool {
        match self.get_last(&word) {
            Some(node) => node.is_word,
            None => false,
        }
    }

    pub fn starts_with(&self, prefix: String) -> bool {
        self.get_last(&prefix).is_some()
    }

    fn get_last(&self, word: &str) -> Option<&PrefixTreeNode> {
        let mut curr = &self.root;
        for c in word.chars() {
            let idx = (c as u8 - b'a') as usize;
            match &curr.children[idx] {
                Some(node) => curr = node,
                None => return None,
            }
        }
        Some(curr)
    }
}

